/**
 * The low-poly unit models (generated by scripts/unit-models.mjs) and how a
 * specific unit wears one: team colour on the `team` material, its affinity
 * colour (glowing) on `accent`, and a skin tone picked from its uid, so the
 * same citizen looks the same in its portrait and on the battlefield.
 */
import * as THREE from 'three'
import type { UnitType } from '../../game'

export const MODEL_URL = (t: UnitType) => `/models/units/${t}.glb?v=3`

/** Team colours in 3D: yours gold, theirs red. */
export const TEAM_HUE = ['#e8c872', '#e0503f'] as const

const SKIN = ['#f1d2b6', '#e0b18c', '#c98f63', '#a86c45', '#7c4a2c', '#d9c2a5', '#b8c9a0', '#9fb2c9']

function hash(s: string) {
  let h = 2166136261
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619)
  return h >>> 0
}

export const skinOf = (uid: string) => SKIN[hash(uid) % SKIN.length]!

export interface Dress {
  team: string
  accent: string
  skin: string
}

/**
 * A ready-to-place copy of a model with its own materials, dressed for one unit.
 * Returns the clone and its materials (the arena flashes them on hits).
 */
export function dressModel(source: THREE.Object3D, dress: Dress) {
  const model = source.clone(true)
  const mats: THREE.MeshStandardMaterial[] = []
  model.traverse((o) => {
    const mesh = o as THREE.Mesh
    if (!mesh.isMesh) return
    const m = (mesh.material as THREE.MeshStandardMaterial).clone()
    if (m.name === 'team') m.color.set(dress.team)
    if (m.name === 'skin') m.color.set(dress.skin)
    if (m.name === 'accent') {
      m.color.set(dress.accent)
      m.emissive.set(dress.accent)
      m.emissiveIntensity = 0.9
    }
    m.userData.baseEmissive = m.emissive.clone()
    m.userData.baseIntensity = m.emissiveIntensity
    mesh.material = m
    mesh.castShadow = true
    mats.push(m)
  })
  return { model, mats }
}

// ── Arms ─────────────────────────────────────────────────────────────────

/** The articulated bits of a model: arms pivot at the shoulders; the weapon is held by one of them. */
export interface ArmRig {
  /** The arm holding the weapon, and the other one. */
  main: THREE.Object3D | null
  off: THREE.Object3D | null
  /** The weapon node (its rotation is the wrist). */
  wrist: THREE.Object3D | null
}

export function armRig(model: THREE.Object3D): ArmRig {
  const wrist = model.getObjectByName('weapon') ?? null
  const main = wrist?.parent && /^arm[LR]$/.test(wrist.parent.name) ? wrist.parent : null
  const off = main ? (model.getObjectByName(main.name === 'armL' ? 'armR' : 'armL') ?? null) : null
  return { main, off, wrist }
}

/**
 * Key poses per type, as [main shoulder, wrist, off shoulder] rotations about x.
 * Arms hang straight down at 0; negative raises them forward. The weapon's own
 * rest points up out of the fist, so wrist angle + shoulder angle is where it points
 * (0 = straight up, +π/2 = straight ahead).
 */
type Key = readonly [number, number, number]
const POSES: Record<UnitType, { rest: Key; windup: Key; strike: Key }> = {
  // Sword up and back over the shoulder, then a downward chop ending pointed ahead.
  fighter: { rest: [-0.3, 1.0, -0.25], windup: [-2.7, 1.0, -0.55], strike: [-0.8, 2.3, -0.35] },
  // Same chop with the hammer; the shield arm stays braced.
  tank: { rest: [-0.25, 0.9, -0.15], windup: [-2.5, 0.8, -0.2], strike: [-0.85, 2.2, -0.2] },
  // Bow arm out straight with the bow upright; the other hand comes up to the string, then lets go.
  ranger: { rest: [-0.2, 0.25, -0.15], windup: [-1.5, 1.5, -1.45], strike: [-1.5, 1.5, -0.95] },
  // Staff held upright; raised high in front, then the head thrust toward the target.
  mage: { rest: [-0.35, 0.35, -0.2], windup: [-2.0, 2.15, -0.9], strike: [-1.45, 2.6, -0.6] },
  healer: { rest: [-0.35, 0.35, -0.2], windup: [-2.0, 2.15, -0.9], strike: [-1.45, 2.6, -0.6] },
}

/**
 * Poses the arms. `windup` (0..1) raises into the wind-up, `strike` (0..1) carries
 * through the blow; both 0 is the resting stance (fade them back to 0 to recover).
 */
export function poseArms(rig: ArmRig, type: UnitType, windup = 0, strike = 0) {
  const { rest, windup: w, strike: s } = POSES[type]
  const at = (i: number) => rest[i]! + (w[i]! - rest[i]!) * windup * (1 - strike) + (s[i]! - rest[i]!) * strike
  if (rig.main) rig.main.rotation.x = at(0)
  if (rig.wrist) rig.wrist.rotation.x = at(1)
  if (rig.off) rig.off.rotation.x = at(2)
}
